import json
import os
import sys
from datetime import datetime, timedelta
from typing import Dict, List, Tuple, Optional, Union

def parse_date(date_str: str) -> Optional[datetime]:
    """Parse date string in various formats to datetime object."""
    if not date_str or date_str.strip() == "":
        return None

    # Remove any leading/trailing whitespace
    date_str = date_str.strip()

    # Try common formats
    formats = [
        "%Y%m%d",        # 20200702
        "%Y-%m-%d",      # 2020-07-02
        "%m/%d/%Y",      # 07/02/2020
        "%d/%m/%Y",      # 02/07/2020
        "%Y/%m/%d",      # 2020/07/02
    ]

    for fmt in formats:
        try:
            return datetime.strptime(date_str, fmt)
        except ValueError:
            continue

    return None

def load_fda_data(packet_dir: str) -> Dict[str, Dict]:
    """Load FDA enforcement reports data."""
    fda_data = {}
    file_path = os.path.join(packet_dir, "fda_enforcement_reports.json")

    try:
        with open(file_path, 'r') as f:
            data = json.load(f)

        for record in data.get("results", []):
            recall_number = record.get("recall_number", "")
            if recall_number:
                fda_data[recall_number] = record
    except (FileNotFoundError, json.JSONDecodeError) as e:
        print(f"Error loading FDA data: {e}", file=sys.stderr)

    return fda_data

def extract_fact_value(record: Dict, fact_name: str, rule_id: str) -> Tuple[Union[str, List[str]], str]:
    """Extract fact value from record based on fact name and rule."""
    if rule_id == "fda.classified_30d":
        if fact_name == "initiation date":
            value = record.get("recall_initiation_date", "")
            doc = "fda_enforcement_reports"
        elif fact_name == "classification date":
            value = record.get("center_classification_date", "")
            doc = "fda_enforcement_reports"
        else:
            return "ABSENT", ""

    elif rule_id == "fda.terminated_180d":
        if fact_name == "initiation date":
            value = record.get("recall_initiation_date", "")
            doc = "fda_enforcement_reports"
        elif fact_name == "termination date":
            value = record.get("termination_date", "")
            doc = "fda_enforcement_reports"
        else:
            return "ABSENT", ""

    else:
        return "ABSENT", ""

    if not value or value.strip() == "":
        return "ABSENT", doc

    # Format date if it's a valid date
    date_obj = parse_date(value)
    if date_obj:
        return date_obj.strftime("%Y-%m-%d"), doc

    return value, doc

def process_pair(pair: str, fda_data: Dict, facts_list: List[str], rule_id: str) -> Dict[str, Union[str, List[str]]]:
    """Process a single pair (rule_id::entity)."""
    entity = pair.split("::")[1]
    record = fda_data.get(entity)

    if not record:
        # If no record found, all facts are ABSENT
        return {fact: "ABSENT" for fact in facts_list}

    result = {}
    fact_values = {}

    # Collect all values for each fact
    for fact in facts_list:
        value, doc = extract_fact_value(record, fact, rule_id)
        fact_values[fact] = (value, doc)

    # Check for conflicts
    for fact in facts_list:
        value, doc = fact_values[fact]

        if value == "ABSENT":
            result[fact] = "ABSENT"
        else:
            result[fact] = [value, doc]

    return result

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>", file=sys.stderr)
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    # Load manifest
    try:
        with open(manifest_path, 'r') as f:
            manifest = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError) as e:
        print(f"Error loading manifest: {e}", file=sys.stderr)
        sys.exit(1)

    # Load FDA data
    fda_data = load_fda_data(packet_dir)

    # Process each pair
    output = {}
    pairs = manifest.get("pairs", [])
    facts = manifest.get("facts", {})

    for pair in pairs:
        rule_id, entity = pair.split("::")
        facts_list = facts.get(rule_id, [])

        result = process_pair(pair, fda_data, facts_list, rule_id)
        output[pair] = result

    # Output as JSON
    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()
