import json
import os
import sys
from datetime import datetime, date
from typing import Dict, List, Tuple, Optional, Union

def parse_date(date_str: str) -> Optional[date]:
    """Parse date from various string formats in FDA data."""
    if not date_str or date_str.strip() == "":
        return None
    # Try common formats
    for fmt in ("%Y%m%d", "%Y-%m-%d", "%Y/%m/%d"):
        try:
            return datetime.strptime(date_str.strip(), fmt).date()
        except ValueError:
            continue
    return None

def load_fda_reports(packet_dir: str) -> Dict[str, Dict]:
    """Load FDA enforcement reports from JSON file."""
    file_path = os.path.join(packet_dir, "fda_enforcement_reports.json")
    with open(file_path, 'r', encoding='utf-8') as f:
        data = json.load(f)

    # Create mapping from recall_number to record
    records = {}
    for record in data.get("results", []):
        recall_num = record.get("recall_number", "")
        if recall_num:
            records[recall_num] = record
    return records

def extract_fact_value(record: Dict, fact_name: str, rule_id: str) -> Union[List[str], str]:
    """Extract value for a specific fact from a record."""
    # Map fact names to field names based on rules
    field_map = {
        "fda.classified_30d": {
            "initiation date": "recall_initiation_date",
            "classification date": "center_classification_date"
        },
        "fda.terminated_180d": {
            "initiation date": "recall_initiation_date",
            "termination date": "termination_date"
        }
    }

    field_name = field_map.get(rule_id, {}).get(fact_name)
    if not field_name:
        return "ABSENT"

    value = record.get(field_name, "")
    if not value or value.strip() == "":
        return "ABSENT"

    # Parse and format date
    parsed_date = parse_date(value)
    if parsed_date:
        formatted_date = parsed_date.strftime("%Y-%m-%d")
        return [formatted_date, "fda_enforcement_reports"]

    return "ABSENT"

def process_manifest(packet_dir: str, manifest_path: str) -> Dict:
    """Process manifest and extract required facts."""
    # Load FDA reports
    fda_records = load_fda_reports(packet_dir)

    # Load manifest
    with open(manifest_path, 'r', encoding='utf-8') as f:
        manifest = json.load(f)

    result = {}

    # Process each pair
    for pair in manifest["pairs"]:
        rule_id, entity = pair.split("::", 1)

        if entity not in fda_records:
            # Entity not found in records
            fact_dict = {}
            for fact_name in manifest["facts"][rule_id]:
                fact_dict[fact_name] = "ABSENT"
            result[pair] = fact_dict
            continue

        record = fda_records[entity]
        fact_dict = {}

        # Extract each fact for this rule
        for fact_name in manifest["facts"][rule_id]:
            fact_dict[fact_name] = extract_fact_value(record, fact_name, rule_id)

        result[pair] = fact_dict

    return result

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    result = process_manifest(packet_dir, manifest_path)
    print(json.dumps(result, indent=2))

if __name__ == "__main__":
    main()
