import json
import os
import sys
from datetime import datetime, timedelta
from pathlib import Path

def parse_date(date_str):
    """Parse date string in YYYYMMDD format to datetime.date object."""
    if not date_str or date_str.strip() == "":
        return None
    try:
        return datetime.strptime(date_str.strip(), "%Y%m%d").date()
    except ValueError:
        return None

def load_fda_data(packet_dir):
    """Load FDA enforcement reports data from JSON file."""
    file_path = Path(packet_dir) / "fda_enforcement_reports.json"
    with open(file_path, 'r', encoding='utf-8') as f:
        data = json.load(f)

    # Create a mapping from recall_number to the record
    records = {}
    for record in data.get("results", []):
        recall_num = record.get("recall_number", "")
        if recall_num:
            records[recall_num] = record
    return records

def extract_fact_value(record, fact_name, rule_id):
    """Extract fact value from record based on fact name and rule."""
    if rule_id == "fda.classified_30d":
        if fact_name == "initiation date":
            date_str = record.get("recall_initiation_date", "")
            return parse_date(date_str), "fda_enforcement_reports"
        elif fact_name == "classification date":
            date_str = record.get("center_classification_date", "")
            return parse_date(date_str), "fda_enforcement_reports"

    elif rule_id == "fda.terminated_180d":
        if fact_name == "initiation date":
            date_str = record.get("recall_initiation_date", "")
            return parse_date(date_str), "fda_enforcement_reports"
        elif fact_name == "termination date":
            date_str = record.get("termination_date", "")
            return parse_date(date_str), "fda_enforcement_reports"

    return None, None

def process_pair(pair, records, facts_map):
    """Process a single pair (rule_id::entity) and return fact values."""
    rule_id, entity = pair.split("::", 1)
    fact_names = facts_map[rule_id]

    result = {}

    # Get the record for this entity
    record = records.get(entity)

    if not record:
        # If no record found, all facts are ABSENT
        for fact_name in fact_names:
            result[fact_name] = "ABSENT"
        return result

    # Collect values for each fact
    fact_values = {}
    for fact_name in fact_names:
        value, source = extract_fact_value(record, fact_name, rule_id)
        if value is None:
            fact_values[fact_name] = ("ABSENT", None)
        else:
            # Format date as YYYY-MM-DD
            formatted_value = value.strftime("%Y-%m-%d")
            fact_values[fact_name] = (formatted_value, source)

    # Check for conflicts
    for fact_name in fact_names:
        value_info = fact_values[fact_name]
        if value_info[0] == "ABSENT":
            result[fact_name] = "ABSENT"
        else:
            result[fact_name] = [value_info[0], value_info[1]]

    return result

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    # Load manifest
    with open(manifest_path, 'r', encoding='utf-8') as f:
        manifest = json.load(f)

    # Load FDA data
    records = load_fda_data(packet_dir)

    # Process all pairs
    output = {}
    for pair in manifest["pairs"]:
        output[pair] = process_pair(pair, records, manifest["facts"])

    # Print JSON output
    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()
